/**
 * Question catalogue.
 *
 * Every question the agent meets (generated by Gemini or found in an
 * application form) is mapped to a canonical `key`. Two questions that mean the
 * same thing ("Quelle est votre nationalité ?" / "Nationality") get the same key,
 * so an answer given once can be reused for every later application instead of
 * asking Yassine again.
 *
 * Pure functions only: this file is used by both the API routes and the
 * dashboard.
 */

export type AnswerType =
  | "text"
  | "textarea"
  | "select"
  | "boolean"
  | "date"
  | "ack";

export type QuestionSpec = {
  key: string;
  label: string;
  type: AnswerType;
  /** Choices offered to the user (select / boolean). */
  options?: string[];
  /** Adds an "Autre" choice with a free text box. */
  allowOther?: boolean;
  /** Legal / personal topic: never invented, always answered by the user. */
  sensitive?: boolean;
  /** Suggest remembering the answer for future applications. */
  remember: boolean;
  /** The answer has a validity date (residence permit...). */
  expires?: boolean;
  hint?: string;
};

export type IncomingQuestion = {
  question: string;
  category?: string | null;
  /** Options found on the real form (select / radio), when known. */
  options?: string[] | null;
  key?: string | null;
};

const YES_NO = ["Oui", "Non"];

export function normalizeText(value: string): string {
  return value
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[’']/g, " ")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

type Rule = { test: RegExp; spec: QuestionSpec };

/** Order matters: the first matching rule wins. */
