const HUMAN_CATEGORIES = new Set(["HUMAN_VERIFICATION", "UNKNOWN_FIELD"]);

const STOPWORDS = new Set(
  "le la les un une des de du d l et ou a au aux en dans pour par sur avec est etes etre vous votre vos quel quelle quels quelles que qui quoi ce cet cette ces il elle nous the of to and or in on for with is are your you what which do does did have has".split(
    " ",
  ),
);

function slug(text: string): string {
  const tokens = normalizeText(text)
    .split(" ")
    .filter((t) => t && !STOPWORDS.has(t));
  return tokens.slice(0, 8).join("_") || "question";
}

/** "Titre : la vraie question ?" → the part after the first colon. */
function stripPrefix(question: string): string {
  const idx = question.indexOf(":");
  const rest = idx > 0 && idx < 60 ? question.slice(idx + 1).trim() : "";
  return rest || question.replace(/:\s*$/, "").trim();
}

function inferType(text: string, options?: string[] | null): QuestionSpec["type"] {
  if (options && options.length) {
    const n = options.map(normalizeText).sort().join("|");
    return n === "non|oui" || n === "no|yes" ? "boolean" : "select";
  }
  const t = normalizeText(text);
  if (
    /^(avez vous|etes vous|souhaitez vous|acceptez vous|pouvez vous|do you|are you|have you|can you|would you)\b/.test(
      t,
    )
  )
    return "boolean";
  if (/\b(date|quand|when)\b/.test(t)) return "date";
  if (t.length > 160) return "textarea";
  return "text";
}

export function classifyQuestion(input: IncomingQuestion): QuestionSpec {
  const category = (input.category || "").toUpperCase();
  const options = input.options?.filter(Boolean) ?? undefined;

  if (HUMAN_CATEGORIES.has(category) || /^intervention humaine/i.test(input.question)) {
    return {
      key: input.key || `${category.toLowerCase() || "human"}_${slug(input.question)}`,
      label: input.question,
      type: "ack",
      remember: false,
      hint: "À faire toi-même dans le formulaire (CAPTCHA, MFA...). Marque comme traité ensuite.",
    };
  }

  const text = normalizeText(input.question);
  for (const rule of RULES) {
    if (rule.test.test(text)) {
      const fromForm = options && options.length ? options : undefined;
      return {
        ...rule.spec,
        options: fromForm ?? rule.spec.options,
        // The real form dictates the choices when it has its own list.
        allowOther: fromForm ? false : rule.spec.allowOther,
        type: fromForm && rule.spec.type !== "textarea" ? "select" : rule.spec.type,
      };
    }
  }

  const clean = stripPrefix(input.question);
  const type = inferType(clean, options);
  return {
    key: input.key || `custom_${slug(clean)}`,
    label: clean.length > 90 ? `${clean.slice(0, 87)}…` : clean,
    type,
    options: type === "boolean" && !options ? YES_NO : options,
    allowOther: false,
    remember: true,
  };
}

/**
 * Finds the option that corresponds to a remembered answer (or null).
 * `loose` also accepts "one contains the other" (only for long enough words,
 * so "Non" never matches "Non concerné(e)").
 */
export function matchOption(
  answer: string,
  options: string[],
  loose = true,
): string | null {
  const a = normalizeText(answer);
  if (!a) return null;
  const normalized = options.map((o) => [o, normalizeText(o)] as const);
  const exact = normalized.find(([, n]) => n === a);
  if (exact) return exact[0];
  if (!loose) return null;
  const partial = normalized.find(
    ([, n]) =>
      n && Math.min(n.length, a.length) >= 5 && (n.includes(a) || a.includes(n)),
  );
  return partial ? partial[0] : null;
}

export function isExpired(expiresAt: string | null | undefined, now = new Date()) {
  if (!expiresAt) return false;
  const d = new Date(expiresAt);
  return !Number.isNaN(d.getTime()) && d.getTime() <= now.getTime();
}

export type StoredAnswer = {
  question_key: string;
  answer: string;
  expires_at?: string | null;
};

/**
 * Decides whether a remembered answer can be reused for a question.
 * Returns the value to store (mapped onto the form's options if needed) or
 * null when the user must be asked again.
 */
export function reuseAnswer(
  spec: QuestionSpec,
  stored: StoredAnswer | undefined,
  now = new Date(),
): string | null {
  if (!stored || spec.type === "ack") return null;
  if (!stored.answer?.trim()) return null;
  if (isExpired(stored.expires_at, now)) return null;
  if (spec.options?.length && !spec.allowOther) {
    return matchOption(stored.answer, spec.options, !spec.sensitive);
  }
  return stored.answer;
}
